import json, re, datetime
from collections import defaultdict

TURKCE_AYLAR = {
    'ocak':1,'şubat':2,'mart':3,'nisan':4,'mayıs':5,'haziran':6,
    'temmuz':7,'ağustos':8,'eylül':9,'ekim':10,'kasım':11,'aralık':12,
}

def parse_tutar(raw):
    if isinstance(raw, (int, float)) and not isinstance(raw, bool):
        return float(raw)
    if not isinstance(raw, str):
        raise ValueError('tutar string degil')
    s = raw
    for ch in ['₺','TL','tl','Tl','tL']:
        s = s.replace(ch, '')
    s = s.replace(' ', '')
    if s == '':
        raise ValueError('bos tutar')
    has_dot = '.' in s
    has_comma = ',' in s
    if has_dot and has_comma:
        s = s.replace('.', '').replace(',', '.')
    elif has_comma and not has_dot:
        s = s.replace(',', '.')
    elif has_dot and not has_comma:
        after = s.split('.')[-1]
        if len(after) == 3 and after.isdigit():
            s = s.replace('.', '')
    return float(s)

def parse_tarih(raw):
    if not isinstance(raw, str):
        raise ValueError('tarih string degil')
    s = raw.strip()
    fmts = ['%Y-%m-%d','%Y/%m/%d','%d.%m.%Y']
    for f in fmts:
        try:
            return datetime.datetime.strptime(s, f).date()
        except ValueError:
            pass
    m = re.match(r'^(\d{1,2})\s+([A-Za-zçÇğĞıİöÖşŞüÜ]+)\s+(\d{4})$', s)
    if m:
        gun = int(m.group(1)); ay_adi = m.group(2).lower(); yil = int(m.group(3))
        ay = TURKCE_AYLAR.get(ay_adi)
        if ay is None:
            raise ValueError('gecersiz ay')
        return datetime.date(yil, ay, gun)
    raise ValueError('tarih formati taninamadi')

path = 'siparisler.jsonl'
with open(path, 'r', encoding='utf-8') as f:
    lines = f.readlines()

records = {}  # id -> record (son gecerli kazanir)
hatali = 0
for line in lines:
    stripped = line.strip()
    if stripped == '':
        continue
    try:
        obj = json.loads(stripped)
    except Exception:
        hatali += 1
        continue
    if not isinstance(obj, dict):
        hatali += 1
        continue
    required = ['id','musteri','tutar','tarih','durum']
    if not all(k in obj for k in required):
        hatali += 1
        continue
    try:
        tutar = parse_tutar(obj['tutar'])
        tarih = parse_tarih(obj['tarih'])
    except Exception:
        hatali += 1
        continue
    musteri = str(obj['musteri']).strip()
    durum = str(obj['durum']).strip().lower()
    records[obj['id']] = {
        'id': obj['id'],
        'musteri': musteri,
        'tutar': tutar,
        'tarih': tarih,
        'durum': durum,
    }

gecerli = len(records)
iptal_sayisi = sum(1 for r in records.values() if r['durum'] == 'iptal')

non_iptal = [r for r in records.values() if r['durum'] != 'iptal']
toplam_tutar = round(sum(r['tutar'] for r in non_iptal), 2)

aylik = defaultdict(float)
for r in non_iptal:
    anahtar = r['tarih'].strftime('%Y-%m')
    aylik[anahtar] += r['tutar']
aylik = {k: round(v, 2) for k, v in sorted(aylik.items())}

musteri_toplari = defaultdict(float)
for r in non_iptal:
    musteri_toplari[r['musteri']] += r['tutar']
en_cok = max(musteri_toplari.items(), key=lambda x: x[1])[0] if musteri_toplari else None

sonuc = {
    'gecerli_kayit': gecerli,
    'hatali_satir': hatali,
    'iptal_sayisi': iptal_sayisi,
    'toplam_tutar': toplam_tutar,
    'aylik': aylik,
    'en_cok_harcayan': en_cok,
}

with open('ozet.json', 'w', encoding='utf-8') as f:
    json.dump(sonuc, f, ensure_ascii=False, indent=2)

print(json.dumps(sonuc, ensure_ascii=False, indent=2))
print('---')
for rid, r in sorted(records.items()):
    print(rid, r['musteri'], r['tutar'], r['tarih'], r['durum'])
print('hatali satir sayisi:', hatali)

